import{_ as o,o as t,c as r,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2021-03-25","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-03-25","date":"2021-03-25T00:00:00.000Z","updated":"2021-03-27T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","缓存管理","数据结构"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-03-25.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-03-25.md","lastUpdated":1780460162000}'),s={name:"posts/2021/Ceph_Performance_Meeting_2021-03-25.md"};function l(i,e,p,a,g,d){return t(),r("div",null,[...e[0]||(e[0]=[n("<p>本次Ceph性能会议讨论了以下关键细节和议题：</p><p><strong>关键细节</strong>：</p><ul><li><strong>PR更新</strong>：过去两周有两个新的PR更新，一个涉及将<code>o_node_map</code>从<code>unordered_map</code>改为<code>std::map</code>，另一个是关于RGW的PR，涉及在RGW压缩后不进行OSD压缩的问题。</li><li><strong>已关闭的PR</strong>：过去两周有三个PR被关闭，包括将alien store线程分散到指定的CPU核心和将bluefs的buffered I/O设置为true。</li><li><strong>性能优化</strong>：动态pen length PR已经合并，解决了对齐问题，并显示出性能提升。Gabby的PR移除了roxdb中的分配，性能改进看起来很好。</li><li><strong>OMAP性能问题</strong>：讨论了bluefs的buffered I/O和omap性能问题，特别是关于hash collisions和数据结构的优化。</li><li><strong>缓存管理</strong>：讨论了缓存分裂和锁定机制的复杂性，提出了简化缓存管理的建议。</li></ul><p><strong>主要议题</strong>：</p><ul><li><strong>数据结构优化</strong>：讨论了如何优化数据结构以减少hash collisions，特别是<code>o_node_map</code>的使用。</li><li><strong>性能问题</strong>：讨论了buffered I/O和omap性能问题，以及如何通过改进缓存管理和数据结构来解决这些问题。</li><li><strong>缓存管理</strong>：讨论了缓存分裂和锁定机制的复杂性，提出了简化缓存管理的建议。</li></ul><p><strong>决定事项</strong>：</p><ul><li><strong>PR合并</strong>：动态pen length PR已经合并，解决了对齐问题，并显示出性能提升。</li><li><strong>数据结构优化</strong>：决定继续讨论和优化<code>o_node_map</code>的数据结构，可能采用<code>std::map</code>或定制的<code>unordered_map</code>。</li><li><strong>缓存管理</strong>：决定继续讨论和简化缓存管理的方案，特别是关于缓存分裂和锁定机制的改进。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li><strong>数据结构优化</strong>：继续讨论和实施<code>o_node_map</code>的数据结构优化方案。</li><li><strong>性能问题</strong>：继续调查和解决buffered I/O和omap性能问题。</li><li><strong>缓存管理</strong>：继续讨论和实施简化缓存管理的方案，特别是关于缓存分裂和锁定机制的改进。</li><li><strong>PR审查</strong>：继续审查和合并相关的PR，确保代码质量和性能优化。</li></ul><p>会议还讨论了关于优化OMAP性能、缓存管理和数据结构优化的问题，并提出了相应的解决方案。</p>",10)])])}const m=o(s,[["render",l]]);export{c as __pageData,m as default};
